  {"id":41132,"x":2813,"y":1790,"nameEn":"Fortune Cascade","nameDe":"Kaskade des Glücks","icon":"","statKey":"lucky_replay_1","tier":"small","descEn":"10% increased chance of obtaining two instead of one additional items when Lucky Drops triggers. Stacks with Jackpot Echo and Overflowing Fortune.","descDe":"10% erhöhte Chance zwei anstatt einem weiteren Gegenstand zu erhalten wenn Glücksfunde aktiviert werden. Wirkt zusammen mit Jackpot-Echo und Überströmendes Glück."},
  {"id":41133,"x":2902,"y":1895,"nameEn":"Jackpot Echo","nameDe":"Jackpot-Echo","icon":"","statKey":"lucky_replay_2","tier":"small","descEn":"15% increased chance of obtaining two instead of one additional items when Lucky Drops triggers. Stacks with Fortune Cascade and Overflowing Fortune.","descDe":"15% erhöhte Chance zwei anstatt einem weiteren Gegenstand zu erhalten wenn Glücksfunde aktiviert werden. Wirkt zusammen mit Kaskade des Glücks und Überströmendes Glück."},
  {"id":41134,"x":3016,"y":1972,"nameEn":"Overflowing Fortune","nameDe":"Überströmendes Glück","icon":"","statKey":"lucky_replay_3","tier":"notable","descEn":"20% increased chance of obtaining two instead of one additional items when Lucky Drops triggers. Stacks with Fortune Cascade and Jackpot Echo.","descDe":"20% erhöhte Chance zwei anstatt einem weiteren Gegenstand zu erhalten wenn Glücksfunde aktiviert werden. Wirkt zusammen mit Kaskade des Glücks und Jackpot-Echo."},
  {"id":41135,"x":3442,"y":634,"nameEn":"Focused Momentum","nameDe":"Fokussierter Schwung","icon":"","statKey":"streak_bonus_1","tier":"small","descEn":"After correctly filling 15 cells in a row without a mistake, gain 15 seconds.","descDe":"Nach 15 korrekt ausgefüllten Zellen in Folge ohne Fehler erhältst du 15 Sekunden."},
  {"id":41136,"x":3575,"y":675,"nameEn":"Flawless Rhythm","nameDe":"Makelloser Rhythmus","icon":"","statKey":"streak_bonus_2","tier":"small","descEn":"Increases the Time gained from Focused Momentum by 5 seconds. Stacks with Perfect Flow.","descDe":"Erhöht die Zeit, die durch Fokussierter Schwung gewonnen wird, um 5 Sekunden. Wirkt zusammen mit Perfekter Fluss."},
  {"id":41137,"x":3708,"y":709,"nameEn":"Perfect Flow","nameDe":"Perfekter Fluss","icon":"","statKey":"streak_bonus_3","tier":"notable","descEn":"Increases the Time gained from Focused Momentum by 10 seconds. Stacks with Flawless Rhythm.","descDe":"Erhöht die Zeit, die durch Fokussierter Schwung gewonnen wird, um 10 Sekunden. Wirkt zusammen mit Makelloser Rhythmus."},
  {"id":41138,"x":1979,"y":818,"nameEn":"Fortune Echo","nameDe":"Echos des Glücks","icon":"","statKey":"bonus_replay_1","tier":"small","descEn":"10% increased chance of Lucky Drops happening.","descDe":"10% erhöhte Chance dass Glücksfunde aktiviert werden."},
  {"id":41139,"x":2079,"y":721,"nameEn":"Golden Recurrence","nameDe":"Goldene Wiederkehr","icon":"","statKey":"bonus_replay_3","tier":"notable","descEn":"20% increased chance of Lucky Drops happening.","descDe":"20% erhöhte Chance dass Glücksfunde aktiviert werden."},
  {"id":41140,"x":1588,"y":1140,"nameEn":"Tutor","nameDe":"Tutor","icon":"","statKey":"tutor_enable","tier":"notable","descEn":"Tutor Items can now be used during an Excercise or Multiple Choice question. The Tutor has a 10% chance of automatically answering the question for you. Requires a Tutor item to be in the inventory and consumes the item on use.","descDe":"Tutor Gegenstände können nun während Übungsaufgaben und Multiple - Choice Fragen verwendet werden. Der Tutor beantwortet die Frage mit 10% Wahrscheinlichkeit automatisch korrekt. Benötigt einen Tutor Gegenstand im Inventar und entfernt den Gegenstand danach aus dem Inventar."},
  {"id":41141,"x":3034,"y":689,"nameEn":"Lucky Drops","nameDe":"Glücksfunde","icon":"","statKey":"lucky_drops","tier":"notable","descEn":"Completing an already completed level has a 25% chance of granting an item.","descDe":"Das erneute Abschließen eines bereits abgeschlossenen Levels gewährt mit 25 % Wahrscheinlichkeit einen Gegenstand."},
  {"id":41142,"x":1888,"y":562,"nameEn":"Elimination Clue","nameDe":"Mörderische Eingebung","icon":"","statKey":"elimination_clue","tier":"notable","descEn":"10% chance to automatically remove one wrong answer from a Multiple Choice question.","descDe":"10% Wahrscheinlichkeit, dass eine falsche Antwort bei Multiple - Choice Fragen automatisch entfernt wird."},
  {"id":41143,"x":2458,"y":280,"nameEn":"Wisdom Through Failure","nameDe":"Weisheit durch Fehler","icon":"","statKey":"wisdom_through_failure","tier":"notable","descEn":"Excercises will show a hint after 5 unsuccessfull attempts.\n10% probability of receiving an additional Item reward when completing an Excercise.","descDe":"Übungsaufgaben zeigen einen Hinweis nach 5 Fehlversuchen.\n10% Wahrscheinlichkeit einen zusätzlichen Gegenstand als Belohnung für das Absolvieren einer Übungsaufgabe zu erhalten."},
  {"id":41144,"x":1582,"y":969,"nameEn":"Pearl of Swiftness","nameDe":"Perle der Gewandheit","icon":"","statKey":"pearl_of_swiftness","tier":"notable","descEn":"Enables the Pearl of Swiftness as an item reward. Using a Pearl of Swiftness reduces the cooldown of your second active class skill to 1 second.","descDe":"Ermöglicht die Perle der Gewandtheit als Gegenstandsbelohnung. Das Benutzen einer Perle der Gewandtheit setzt die Abklingzeit deiner zweiten aktiven Klassenfähigkeit auf 1 Sekunde."},
  {"id":41145,"x":1984,"y":1153,"nameEn":"The Witch","nameDe":"Die Hexe","icon":"","statKey":"keystone_the_witch","tier":"keystone","descEn":"Enables The Witch as an item reward. Using The Witch grants immunity to all cursed item downsides for 60 seconds, but reduces the timer by 10 minutes.","descDe":"Ermöglicht Die Hexe als Gegenstandsbelohnung. Das Benutzen der Hexe gewährt 60 Sekunden Immunität gegen alle negativen Effekte verfluchter Gegenstände, reduziert aber den Timer um 10 Minuten."},
  {"id":41146,"x":1210,"y":2238,"nameEn":"Gambler's Ruin","nameDe":"Ruin des Spielers","icon":"","statKey":"keystone_gamblers_ruin","tier":"keystone","descEn":"Each correct cell fill adds 3 seconds to the timer. Each mistake removes 20 additional seconds from the timer. Bonus time from all other sources is disabled.","descDe":"Jede korrekt ausgefüllte Zelle fügt dem Timer 3 Sekunden hinzu. Jeder Fehler entfernt 20 zusätzliche Sekunden vom Timer. Bonuszeit aus allen anderen Quellen ist deaktiviert."},
  {"id":41147,"x":1143,"y":1729,"nameEn":"Scholar's Debt","nameDe":"Gelehrten-Schuld","icon":"","statKey":"keystone_scholars_debt","tier":"keystone","descEn":"You start every level with double time - but 30 seconds are deducted every 60 seconds.","descDe":"Du startest jedes Level mit doppelter Zeit – aber alle 60 Sekunden werden 30 Sekunden abgezogen."},
  {"id":41148,"x":-1834,"y":1397,"nameEn":"Martingale","nameDe":"Martingal","icon":"","statKey":"keystone_martingale","tier":"keystone","descEn":"You carry a payout stake starting at 15 seconds. Every mistake doubles it, up to a maximum of 480 seconds. Every fully completed line pays out the stake as bonus time and resets it back to 15 seconds.","descDe":"Du führst einen Auszahlungs-Einsatz ab 15 Sekunden. Jeder Fehler verdoppelt ihn, bis zu einem Maximum von 480 Sekunden. Jede vollständig abgeschlossene Linie zahlt den Einsatz als Bonuszeit aus und setzt ihn auf 15 Sekunden zurück."},
  {"id":41149,"x":1721,"y":1493,"nameEn":"Zero Variance","nameDe":"Nullvarianz","icon":"","statKey":"keystone_zero_variance","tier":"keystone","descEn":"Every mistake costs exactly 30 seconds - no matter how far into the level you are, which class you play or what modifiers are active.","descDe":"Jeder Fehler kostet exakt 30 Sekunden – egal wie weit du im Level bist, welche Klasse du spielst oder welche Modifikatoren aktiv sind."},
  {"id":41150,"x":-2087,"y":2148,"nameEn":"Perpetual Frost","nameDe":"Ewiger Frost","icon":"","statKey":"keystone_perpetual_frost","tier":"keystone","descEn":"Every fully completed line freezes the timer for 8 seconds.","descDe":"Jede vollständig abgeschlossene Linie friert den Timer für 8 Sekunden ein."},
  {"id":41151,"x":1296,"y":1592,"nameEn":"Overfitting","nameDe":"Überanpassung","icon":"","statKey":"keystone_overfitting","tier":"keystone","descEn":"The first 15% of cells you fill are filled for free - mistakes in this phase cost no time. After 50% completion, each mistake costs triple the normal time.","descDe":"Die ersten 15% der Zellen, die du ausfüllst, sind kostenlos - Fehler in dieser Phase kosten keine Zeit. Nach 50% Abschluss kostet jeder Fehler dreimal so viel Zeit wie normal."},
  {"id":41152,"x":1432,"y":1455,"nameEn":"Asymptotic Mastery","nameDe":"Asymptotische Meisterschaft","icon":"","statKey":"keystone_asymptotic_mastery","tier":"keystone","descEn":"Each completed row or column permanently reduces the time cost of all future mistakes in this level by 5 seconds. Shields of all kinds are disabled.","descDe":"Schlüsselfertigkeit: Jede abgeschlossene Zeile oder Spalte reduziert die Zeitkosten aller zukünftigen Fehler in diesem Level dauerhaft um 5 Sekunden. Schilde jeder Art sind deaktiviert."},
  {"id":41153,"x":-2041,"y":800,"nameEn":"Iron Doctrine","nameDe":"Eiserne Doktrin","icon":"","statKey":"keystone_iron_doctrine","tier":"keystone","descEn":"Shield items cannot be used. Each mistake costs 20 extra seconds. Tutor and Timer items have 300% increased effectiveness.","descDe":"Schild-Gegenstände können nicht benutzt werden. Jeder Fehler kostet 20 zusätzliche Sekunden. Tutor- und Timer-Gegenstände haben 300% erhöhte Effektivität."},
  {"id":41154,"x":-742,"y":1868,"nameEn":"Countdown Crisis","nameDe":"Countdown-Krise","icon":"","statKey":"keystone_countdown_crisis","tier":"keystone","descEn":"Timer items reduce the timer instead of increasing it. Reveal items are 5 times as strong while the timer is below 3 minutes.","descDe":"Timer-Gegenstände reduzieren den Timer anstatt ihn zu erhöhen. Enthüllungsgegenstände sind 5-mal so stark, während der Timer unter 3 Minuten liegt."},
  {"id":41155,"x":-1743,"y":1622,"nameEn":"Veil of Purity","nameDe":"Schleier der Reinheit","icon":"","statKey":"keystone_veil_of_purity","tier":"keystone","descEn":"The first cursed item used each level has no downside. Any further use of a cursed item has double the downside.","descDe":"Der erste verfluchte Gegenstand pro Level hat keine negativen Effekte. Jeder weitere verfluchte Gegenstand hat doppelt so starke negative Effekte."},
  {"id":41156,"x":-476,"y":-2277,"nameEn":"Thin Margin","nameDe":"Schmaler Grat","icon":"","statKey":"keystone_thin_margin_41156","tier":"keystone","descEn":"-3 Allowed Mistakes\n25% more maximum Life","descDe":"-3 erlaubte Fehler\n25% mehr maximales Leben","effects":["mistake_count:-3"]},
  {"id":41157,"x":-11,"y":-3243,"nameEn":"Frequentist's Burden","nameDe":"Last des Frequentisten","icon":"","statKey":"keystone_frequentists_burden","tier":"keystone","descEn":"Hides all row and column clues. Every 5 correct cell fills 1 random clue gets revealed. Reduces all Class Ability cooldowns by 15 seconds.","descDe":"Versteckt alle Zeilen - und Spaltenhinweise. Alle 5 korrekt ausgefüllten Zellen wird ein Hinweis wieder angezeigt. Reduziert die Abklingzeit aller Klassenfähigkeiten um 15 Sekunden."},
  {"id":41158,"x":-2106,"y":-462,"nameEn":"Sparse Prior","nameDe":"Schwacher Prior","icon":"","statKey":"keystone_sparse_prior","tier":"keystone","descEn":"All row and column clues are hidden at the start of the level. Each completed row or column reveals the clues of all adjacent rows and columns.","descDe":"Alle Zeilen- und Spaltenhinweise sind zu Beginn des Levels verborgen. Jede abgeschlossene Zeile oder Spalte enthüllt die Hinweise aller benachbarten Zeilen und Spalten."},
  {"id":41159,"x":-3446,"y":647,"nameEn":"Cartographer's Oath","nameDe":"Eid des Kartographen","icon":"","statKey":"keystone_cartographers_oath","tier":"keystone","descEn":"The entire border ring of the grid is resolved at the start of each level: filled border cells are revealed and empty border cells are automatically marked as incorrect.","descDe":"Der gesamte Rand des Gitters wird zu Beginn jedes Levels aufgelöst: Gefüllte Randzellen werden aufgedeckt und leere Randzellen werden automatisch als falsch markiert."},
  {"id":41160,"x":572,"y":-2267,"nameEn":"Kolmogorov Complexity","nameDe":"Kolmogorow-Komplexität","icon":"","statKey":"keystone_kolmogorov","tier":"keystone","descEn":"All clue numbers are compressed: each row and column only shows its first and last run length. Everything in between stays hidden.","descDe":"Alle Hinweiszahlen werden komprimiert: Jede Reihe und Spalte zeigt nur ihre erste und letzte Blocklänge. Alles dazwischen bleibt verborgen."},
  {"id":41161,"x":436,"y":-2224,"nameEn":"Uniform Prior","nameDe":"Uniformer Prior","icon":"","statKey":"keystone_uniform_prior","tier":"keystone","descEn":"All clue numbers are shuffled between the lines at the start of each level, but you start with 3 free reveals. Every fully completed line restores its true clues and grants +3 seconds.","descDe":"Alle Hinweiszahlen werden zu Beginn jedes Levels zwischen den Linien gemischt, aber du beginnst mit 3 kostenlosen Aufdeckungen. Jede vollständig abgeschlossene Linie stellt ihre wahren Hinweise wieder her und gewährt +3 Sekunden."},
  {"id":41162,"x":-2146,"y":656,"nameEn":"Nightfall Protocol","nameDe":"Nachtprotokoll","icon":"","statKey":"keystone_nightfall_protocol","tier":"keystone","descEn":"All clue numbers are hidden for the first minute of every level. When night lifts, all clues return and you are rewarded with 3 free reveals.","descDe":"Alle Hinweiszahlen sind in der ersten Minute jedes Levels verborgen. Wenn die Nacht weicht, kehren alle Hinweise zurück und du wirst mit 3 kostenlosen Aufdeckungen belohnt."},
  {"id":41163,"x":818,"y":-2304,"nameEn":"Dead Reckoning","nameDe":"Koppelnavigation","icon":"","statKey":"keystone_dead_reckoning","tier":"keystone","descEn":"At the start of each level, every row and column clue is shown as the sum of the amount of filled cells in this row and column instead of the exact value. Completing 25% of the grid reveals all exact clues. Increases the Timer by 30%.","descDe":"Zu Beginn jedes Levels wird jeder Zeilen- und Spaltenhinweis als Summe statt als genauen Wert angezeigt. Das Abschließen von 25% des Gitters enthüllt alle genauen Hinweise. Erhöht den Timer um 30%."},
  {"id":41164,"x":-1966,"y":-754,"nameEn":"Maximum Likelihood","nameDe":"Maximale Wahrscheinlichkeit","icon":"","statKey":"keystone_maximum_likelihood","tier":"keystone","descEn":"At the start of each level, the single row and single column with the most filled cells are fully solved automatically. You start the level with 30% less time on the timer.","descDe":"Zu Beginn jedes Levels werden die Zeile und die Spalte mit den meisten gefüllten Zellen automatisch vollständig gelöst. Du startest das Level mit 30% weniger Zeit auf dem Timer."},
  {"id":41165,"x":-511,"y":-3169,"nameEn":"Blinding Truth","nameDe":"Blendende Wahrheit","icon":"","statKey":"keystone_blinding_truth","tier":"keystone","descEn":"Reveal items are 50% more effective. Mark-wrong items cannot be used.","descDe":"Enthüllungsgegenstände sind 50% effektiver. Markierungsgegenstände können nicht benutzt werden."},
  {"id":41166,"x":2392,"y":849,"nameEn":"Null Hypothesis","nameDe":"Nullhypothese","icon":"","statKey":"keystone_null_hypothesis","tier":"keystone","descEn":"At the start of each level, all incorrect empty cells in the row and column with the fewest filled cells are automatically marked. You cannot gain mistake shields of any kind.","descDe":"Zu Beginn jedes Levels werden alle falschen leeren Zellen in der Zeile und Spalte mit den wenigsten gefüllten Zellen automatisch markiert. Du kannst keine Fehlerschilde jeglicher Art erhalten."},
  {"id":41167,"x":2018,"y":506,"nameEn":"Law of Large Numbers","nameDe":"Gesetz der Großen Zahlen","icon":"","statKey":"keystone_law_of_large_numbers","tier":"keystone","descEn":"Every 2 minutes, automatically reveal one row and column with fewer than 2 correct filled cells. This effect does not trigger in the last minute of a level.","descDe":"Alle 2 Minuten wird automatisch eine Zeile oder Spalte mit weniger als 2 korrekt gefüllten Zellen aufgedeckt. Dieser Effekt löst in der letzten Minute eines Levels nicht aus."},
  {"id":41169,"x":2213,"y":332,"nameEn":"Axiom of Choice","nameDe":"Auswahlaxiom","icon":"","statKey":"keystone_axiom_of_choice","tier":"keystone","descEn":"Once per level, when the timer first drops below 25%, 5% of all remaining correct cells are revealed instantly. This effect triggers automatically.","descDe":"Einmal pro Level, wenn der Timer erstmals unter 25% fällt, werden 5% aller verbleibenden korrekten Zellen sofort aufgedeckt. Dieser Effekt löst automatisch aus."},
  {"id":41170,"x":2556,"y":92,"nameEn":"Type I Error","nameDe":"Fehler 1. Art","icon":"","statKey":"keystone_type_i_error","tier":"keystone","descEn":"Your first ✕ mark of every level resonates: ALL truly empty cells of that row AND column are mass-marked instantly.","descDe":"Dein erstes ✕-Zeichen jedes Levels hallt nach: ALLE wirklich leeren Zellen dieser Reihe UND Spalte werden sofort massenmarkiert."},
  {"id":41171,"x":1735,"y":1176,"nameEn":"Variance Collapse","nameDe":"Varianzkollaps","icon":"","statKey":"keystone_variance_collapse","tier":"keystone","descEn":"Lucky Tiles appear in all grids regardless of size. Revealing a Lucky Tile reduces the Timer by 15%.","descDe":"Glücksfelder erscheinen in allen Gittern unabhängig von der Größe. Das Enthüllen eines Glücksfelds reduziert den Timer um 15%."},
  {"id":41172,"x":3323,"y":824,"nameEn":"Curse Embrace","nameDe":"Fluchsumarmung","icon":"","statKey":"keystone_curse_embrace","tier":"keystone","descEn":"You are immune to cursed item downsides. Reveal, Mark-wrong, Timer and Eraser items are 50% weaker.","descDe":"Du bist immun gegen negative Effekte verfluchter Gegenstände. Aufdeck-, Markier-, Timer- und Radier-Gegenstände sind 50% schwächer."},
  {"id":41173,"x":2266,"y":1251,"nameEn":"Open Bazaar","nameDe":"Offener Basar","icon":"","statKey":"keystone_open_bazaar","tier":"keystone","descEn":"Every item use during a level reveals 2 correct cells and grants an additional 5 seconds.","descDe":"Jede Gegenstandsbenutzung während eines Levels deckt 2 korrekte Zellen auf und gewährt zusätzlich 5 Sekunden."},
  {"id":41174,"x":1514,"y":1296,"nameEn":"Philosopher's Grid","nameDe":"Gitter des Philosophen","icon":"","statKey":"keystone_philosophers_grid","tier":"keystone","descEn":"Lucky tiles no longer shimmer and are completely invisible. In exchange, claiming one grants 60 additional seconds and reveals 2 cells.","descDe":"Glückskacheln schimmern nicht mehr und sind komplett unsichtbar. Dafür gewährt das Einsammeln 60 zusätzliche Sekunden und deckt 2 Zellen auf."},
  {"id":41175,"x":2118,"y":843,"nameEn":"Borrowed Hours","nameDe":"Geliehene Stunden","icon":"","statKey":"keystone_borrowed_hours_41175","tier":"keystone","descEn":"+600 seconds added to the Timer\n-4 Allowed Mistakes","descDe":"+600 Sekunden zum Timer hinzugefügt\n-4 erlaubte Fehler","effects":["time_added:600","mistake_count:-4"]},
  {"id":41176,"x":1581,"y":1465,"nameEn":"Long Game","nameDe":"Langes Spiel","icon":"","statKey":"keystone_long_game_41176","tier":"keystone","effects":["time_added:600","long_game_no_gain"]},
  {"id":41177,"x":2343,"y":1760,"nameEn":"Glass Clock","nameDe":"Glasuhr","icon":"","statKey":"keystone_glass_clock_41177","tier":"keystone","effects":["glass_clock_timer:25","glass_clock_gain"]},
  {"id":41178,"x":-2346,"y":634,"nameEn":"Perfectionist","nameDe":"Perfektionist","icon":"","statKey":"keystone_perfectionist_41178","tier":"keystone","effects":["mistake_count:6","perfectionist_cost:100"]},
  {"id":41179,"x":3272,"y":-528,"nameEn":"Marathon","nameDe":"Marathon","icon":"","statKey":"keystone_marathon_41179","tier":"keystone","effects":["marathon_size"]},
  {"id":1001,"x":-1640,"y":840,"nameEn":"Character Start: Stox","nameDe":"Charakter-Start: Stox","descEn":"Character start node for Stox","descDe":"Charakter-Startknoten für Stox","icon":"◉","statKey":"character_start_stox","tier":"start","sprite":"images/sprites/Stox_noclass.webp"},
  {"id":1002,"x":0,"y":-1810,"nameEn":"Character Start: Trix","nameDe":"Charakter-Start: Trix","descEn":"Character start node for Trix","descDe":"Charakter-Startknoten für Trix","icon":"◉","statKey":"character_start_trix","tier":"start","sprite":"images/sprites/Trix_noclass.webp"},
  {"id":1003,"x":1560,"y":800,"nameEn":"Character Start: Syla","nameDe":"Charakter-Start: Syla","descEn":"Character start node for Syla","descDe":"Charakter-Startknoten für Syla","icon":"◉","statKey":"character_start_syla","tier":"start","sprite":"images/sprites/Syla_noclass.webp"}
